fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol should be positive, but handle gracefully
    if tol <= 0 {
        return false;
    }
    
    // Use i16 to avoid overflow when computing difference
    let diff = a as i16 - b as i16;
    diff > -(tol as i16) && diff < tol as i16
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions from problem: vectors have equal, non-zero length
    // tol should be positive, but handle gracefully
    if tol <= 0 {
        return vec![false; a.len()];
    }
    
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}